  const NY = D.PELVIS_Y + D.NECK_Y;
  b.tube(MAT.skin, 6, 'y', t => { const y = 1.54 + t * .19; return { c: [0, y, .005], a: .056 * bd.neck, b: .054 * bd.neck } }, (x, y) => blend(y, 1.59, NY + .02, B.spine, B.neck));
